insert into public.products (id, name, category, description, image_path, price_cents, sort_order, legacy_record) values
    ('burger', 'Burger', 'Meals', 'Beef patty, melted cheese and crisp lettuce on a brioche bun.', '/assets/burger.jpg', 1232, 0, '{"table":"foods","origin":"local_postgres","row":{"id":1,"body":"Sizzling on the grill, a symphony of savory aromas wafts through the air, as succulent beef patties are nestled between toasted brioche buns, adorned with crisp lettuce, juicy tomatoes, tangy pickles, and a smattering of melted cheese, creating a mouthwatering masterpiece that promises to tantalize taste buds and satisfy cravings with every indulgent bite of this quintessential culinary delight known as the burger.","food_name":"Burger","food_image":"/assets/burger.jpg","price":"12.32"}}'::jsonb),
    ('fried-chicken', 'Fried Chicken', 'Meals', 'Seasoned chicken with a crisp golden coating.', '/assets/friedchicken.jpg', 829, 1, '{"table":"foods","origin":"local_postgres","row":{"id":3,"body":"In a symphony of sizzling anticipation, plump pieces of chicken are bathed in a golden bath of bubbling oil, their tender flesh encased in a crispy, flavorful armor that crackles with each bite, releasing a burst of succulent juiciness that dances on the tongue, tantalizing taste buds with a harmonious medley of spices and seasonings that sing of comfort and culinary mastery, as each bite transports you to a realm of fried chicken bliss, where crispy perfection meets soul-satisfying satisfaction, making every crunchy mouthful a celebration of flavor and texture that leaves you longing for just one more crispy piece.","food_name":"Fried Chicken","food_image":"/assets/friedchicken.jpg","price":"8.29"}}'::jsonb),
    ('fries', 'Fries', 'Sides', 'Golden, lightly salted fries.', '/assets/fries.jpg', 327, 2, '{"table":"foods","origin":"local_postgres","row":{"id":2,"body":"Golden fingers of potato perfection, crispy and irresistible, emerge from bubbling oil, their heavenly aroma filling the air with promises of crunchy delight, as each slender strip is seasoned to perfection with a sprinkle of salt, offering a symphony of flavors that dance on the palate with every satisfying crunch, making each bite a delectable journey of savory satisfaction, ensuring that these humble yet iconic fries remain an eternal companion to the beloved burger, a dynamic duo that ignites the senses and leaves taste buds yearning for more.","food_name":"Fries","food_image":"/assets/fries.jpg","price":"3.27"}}'::jsonb),
    ('nuggets', 'Nuggets', 'Sides', 'Bite-size pieces of breaded chicken.', '/assets/nuggets.jpg', 729, 3, '{"table":"foods","origin":"local_postgres","row":{"id":4,"body":"Crafted from tender cuts of chicken, each nugget is a bite-sized treasure, coated in a crunchy golden shell that promises a symphony of flavors with every satisfying crunch, as the succulent meat within offers a burst of savory delight that melts on the tongue, while the perfectly seasoned breading adds a hint of spice and a touch of crispiness that keeps you reaching for more, creating a culinary adventure that delights both young and old alike, as these delectable nuggets prove that good things truly do come in small, crispy packages, inviting you to savor the joy of each bite, one nugget at a time.","food_name":"Nuggets","food_image":"/assets/nuggets.jpg","price":"7.29"}}'::jsonb),
    ('coca-cola', 'Coca-Cola', 'Canned drinks', 'Classic cola, served chilled.', '/assets/cocacola.jpg', 300, 4, '{"table":"canned_drinks","origin":"local_postgres","row":{"id":1,"body":"Indulge in the classic, effervescent delight of Coca-Cola, a timeless beverage that transcends generations, tantalizing taste buds with its iconic blend of flavors. With each sip, experience a symphony of carbonation and sweetness that dances on your palate, leaving you refreshed and invigorated. From its humble beginnings to its global reign as a symbol of refreshment, Coca-Cola continues to captivate hearts and minds, inviting you to savor the simple joys in life, one delicious sip at a time.","canned_name":"cocacola","canned_image":"/assets/cocacola.jpg","price":"3.00"}}'::jsonb),
    ('royal', 'Royal', 'Canned drinks', 'Orange soda, served chilled.', '/assets/royal.jpg', 127, 5, '{"table":"canned_drinks","origin":"local_postgres","row":{"id":2,"body":"Step into the realm of refreshment fit for royalty with Royal Soda, where every effervescent sip is a coronation of flavor and indulgence. From the grand halls of taste to the throne of satisfaction, our regal blend of exquisite ingredients reigns supreme, captivating taste buds with its majestic allure and timeless charm. Crafted for those who appreciate the finer things in life, Royal Soda is more than a beverage - it''s a symbol of elegance and refinement, elevating every moment into a royal occasion. Join the noble ranks of connoisseurs and experience the enchanting journey of flavor fit for kings and queens, as Royal Soda crowns your palate with unparalleled delight, one luxurious sip at a time.","canned_name":"Royal","canned_image":"/assets/royal.jpg","price":"1.27"}}'::jsonb),
    ('sprite', 'Sprite', 'Canned drinks', 'Lemon-lime soda, served chilled.', '/assets/sprite.jpg', 100, 6, '{"table":"canned_drinks","origin":"local_postgres","row":{"id":3,"body":"Embark on a sparkling adventure with Sprite Soda, where every bubbly sip is a refreshing burst of citrus delight that dances on your taste buds like a lively celebration. From its crisp, clean taste to its invigorating fizz, Sprite Soda is your passport to a world of zesty refreshment, beckoning you to quench your thirst with its vibrant charm and effervescent personality. Whether you''re basking in the sunshine or seeking a pick-me-up on a dreary day, Sprite Soda is your loyal companion, ready to uplift your spirits and tantalize your senses with its irresistible flavor. Join the countless fans who have embraced the refreshing sensation of Sprite Soda and let it spark joy in every sip, as you savor the effervescent magic that makes every moment brighter and more refreshing.","canned_name":"Sprite","canned_image":"/assets/sprite.jpg","price":"1.00"}}'::jsonb),
    ('mountain-dew', 'Mountain Dew', 'Canned drinks', 'Citrus soda, served chilled.', '/assets/mountaindew.jpg', 300, 7, '{"table":"canned_drinks","origin":"local_postgres","row":{"id":4,"body":"Embrace the electrifying thrill of the dew with Mountain Dew Soda, where each exhilarating gulp is a surge of citrus-infused excitement that ignites your senses like a rush of adrenaline. From its bold, neon-green hue to its tantalizing fusion of lemon-lime flavor, Mountain Dew Soda is more than just a drink - it''s a jolt of pure refreshment that fuels your adventurous spirit and propels you to new heights of taste sensation. Whether you''re tackling the toughest challenges or simply seeking a burst of energy, Mountain Dew Soda is your ultimate companion, ready to unleash a wave of fizzy exhilaration that leaves you buzzing with excitement. Join the legion of thrill-seekers and experience the electrifying rush of Mountain Dew Soda, as you dive headfirst into a world of unbridled flavor and unstoppable energy.","canned_name":"Mountain Dew","canned_image":"/assets/mountaindew.jpg","price":"3.00"}}'::jsonb),
    ('chocolate-smoothie', 'Chocolate Smoothie', 'Smoothies & frappes', 'A blended chocolate smoothie.', '/assets/chocolateSmoothie.jpg', 254, 8, '{"table":"sweet_drinks","origin":"local_postgres","row":{"id":1,"body":"In the heart of a bustling morning, as sunlight dances through the kitchen window, blending with the aroma of freshly brewed coffee, there exists a tantalizing concoction awaiting creation - a decadent symphony of velvety cocoa, creamy almond milk, ripe bananas, and a hint of nutty indulgence, all whirled together into a luscious chocolate smoothie, promising a moment of pure bliss with each sip, a harmonious fusion of richness and refreshment that transports the palate to a paradise of sweetness and satisfaction, where every velvety gulp whispers tales of comfort and joy, awakening the senses to the magic of chocolate in its most enchanting form.","sweets_name":"Chocolate Smoothie","sweets_image":"/assets/chocolateSmoothie.jpg","price":"2.54"}}'::jsonb),
    ('vanilla-smoothie', 'Vanilla Smoothie', 'Smoothies & frappes', 'A blended vanilla smoothie.', '/assets/vanillaSmoothie.jpg', 127, 9, '{"table":"sweet_drinks","origin":"local_postgres","row":{"id":2,"body":"In the tranquility of a serene afternoon, as gentle breezes sway the curtains and sunlight bathes the room in a golden glow, there exists a delightful elixir awaiting crafting - a heavenly blend of creamy vanilla bean, chilled coconut milk, succulent strawberries, and a touch of honeyed sweetness, all swirled together into a velvety vanilla smoothie, promising a moment of pure delight with every sip, a symphony of flavors that dances on the taste buds, evoking memories of lazy summer days and carefree indulgence, where each luxuriously smooth mouthful transports the soul to a realm of serenity and contentment, where the essence of vanilla reigns supreme, casting its enchanting spell of comfort and harmony upon all who partake.","sweets_name":"Vanilla Smoothie","sweets_image":"/assets/vanillaSmoothie.jpg","price":"1.27"}}'::jsonb),
    ('mocha-frappe', 'Mocha Frappe', 'Smoothies & frappes', 'Espresso and chocolate blended with ice.', '/assets/mocha.jpg', 625, 10, '{"table":"sweet_drinks","origin":"local_postgres","row":{"id":3,"body":"In the midst of a bustling urban landscape, where skyscrapers kiss the sky and the rhythm of city life pulses through the streets, there exists an irresistible temptation waiting to be savored - a decadent fusion of bold espresso, rich chocolate syrup, velvety milk, and a flurry of ice, all expertly blended into a tantalizing mocha frappe, promising a moment of sheer indulgence with every icy sip, a symphony of flavors that dances on the palate, awakening the senses to the intoxicating marriage of coffee and chocolate, where each velvety mouthful delivers a jolt of caffeine-infused bliss, igniting a spark of energy amidst the urban hustle, while the smooth caress of chocolate whispers tales of comfort and satisfaction, enveloping the soul in a delicious embrace that transcends the chaos of the city, offering a fleeting escape to a world where pleasure reigns supreme.","sweets_name":"Mocha Frappe","sweets_image":"/assets/mocha.jpg","price":"6.25"}}'::jsonb),
    ('cookies-and-cream-frappe', 'Cookies & Cream Frappe', 'Smoothies & frappes', 'A chilled blend of chocolate cookies and vanilla.', '/assets/cookieFrappe.jpg', 327, 11, '{"table":"sweet_drinks","origin":"local_postgres","row":{"id":4,"body":"Amidst the whimsical charm of a sunlit caf‚, where laughter mingles with the aroma of freshly baked goods and the gentle hum of conversation fills the air, there exists a delightful creation awaiting discovery - a dreamy fusion of crumbled chocolate cookies, velvety vanilla ice cream, chilled milk, and a flurry of ice, all expertly blended into a decadent cookies & cream frappe, promising a moment of pure indulgence with every creamy sip, a symphony of flavors that dances upon the palate, evoking childhood memories of sweet treats and carefree afternoons, where each velvety mouthful is a journey to a realm of whimsy and delight, where the comforting embrace of cookies and cream whispers tales of nostalgia and joy, enveloping the senses in a delicious symphony of sweetness that transports the soul to a world where every sip is a celebration of life''s simple pleasures.","sweets_name":"Cookies & Cream Frappe","sweets_image":"/assets/cookieFrappe.jpg","price":"3.27"}}'::jsonb),
    ('citrus-burst', 'Citrus Burst', 'Fruit drinks', 'A bright blend of citrus flavors.', '/assets/citrus-burst.png', 2232, 12, '{"table":"burst_drinks","origin":"local_postgres","row":{"id":1,"body":"Bursting with the vibrant essence of sun-kissed citrus fruits, each sip of this effervescent elixir is a tantalizing journey through orchards of tangy delights, as zesty lemon, tangy lime, and sweet orange mingle in a symphony of flavors that dance on the palate, refreshing and invigorating with every delightful fizz, while hints of tropical bliss add a tantalizing twist to this citrus sensation, leaving taste buds tingling with the perfect balance of sweet and sour, and a refreshing coolness that revitalizes the senses, making every sip an exhilarating celebration of citrusy perfection that brightens even the dreariest of days.","burst_name":"Citrus Burst","burst_image":"/assets/citrus-burst.png","price":"22.32"}}'::jsonb),
    ('yellow-citrus', 'Yellow Citrus', 'Fruit drinks', 'A sweet and tart citrus drink.', '/assets/yellowDrink.jpg', 1027, 13, '{"table":"burst_drinks","origin":"repository_seed","row":{"body":"Immersed in the golden glow of the sun’s embrace, this radiant elixir is a burst of sunshine captured in a glass, as tangy notes of lemon and lime intertwine with the sweet embrace of sun-kissed oranges, creating a symphony of citrus flavors that dance on the palate with every sip, invigorating and refreshing like a gentle breeze on a summer''s day. With its vibrant hue and zesty essence, this yellow citrus drink is a beacon of brightness, lifting spirits and rejuvenating the senses with its tantalizing blend of tartness and sweetness, reminding you that every sip is a sip of pure liquid sunshine, a refreshing oasis in a world of thirst-quenching delight.","burst_name":"Yellow Citrus","burst_image":"/assets/yellowDrink.jpg","price":"10.27"}}'::jsonb),
    ('clear-spartan', 'Clear Spartan', 'Fruit drinks', 'A lightly flavored, clear refreshment.', '/assets/clearDrink.jpg', 1923, 14, '{"table":"burst_drinks","origin":"repository_seed","row":{"body":"As clear as the pristine waters of ancient Sparta, this invigorating elixir is a testament to purity and strength, with a taste as crisp and refreshing as the mountain springs of the rugged Greek landscape. Infused with the essence of Spartan discipline, each sip of this transparent tonic revitalizes the weary warrior within, energizing the body and sharpening the mind with a surge of clarity and focus. With its clean, uncompromising flavor and thirst-quenching power, this clear Spartan drink embodies the resilience and fortitude of its namesake, offering a refreshing respite for modern-day champions in their quest for victory and vitality.","burst_name":"Clear Spartan","burst_image":"/assets/clearDrink.jpg","price":"19.23"}}'::jsonb);
